        ptr += 1
        A = list(map(int, input[ptr:ptr+N]))
        ptr += N

        if N == 1:
            print(A[0])
            continue

        freq = {}
        for num in A:
            freq[num] = freq.get(num, 0) + 1

        if len(freq) == 1:
